import { getSlider, getCheckBox } from '../Utils';
import { showGraphDrone, showGraph, showCamera } from './DataViz';

import { Solution } from '..';

export class View {
	public solution: Solution;

	public metadataPosition: HTMLDivElement;

	private divContainer: HTMLDivElement = undefined;
	private divUI: HTMLDivElement = undefined;
	private divUILeft: HTMLDivElement = undefined;
	private divUIRight: HTMLDivElement = undefined;

	private _color = '#333';
	private _fontSize = '11px';
	private _width = '150px';
	private _showUI = false;

	constructor(solution: Solution) {
		this.solution = solution;

		const divTitle = document.createElement('div');
		divTitle.textContent = 'Hypercube Sandbox';
		divTitle.style.fontSize = '34px';
		divTitle.style.fontWeight = '800';
		divTitle.style.width = '100%';
		divTitle.style.height = '100px';
		divTitle.style.position = 'absolute';
		divTitle.style.textAlign = 'center';
		divTitle.style.zIndex = '10';
		divTitle.style.pointerEvents = 'none';
		this.solution.threeCore.host.appendChild(divTitle);

		this.divContainer = document.createElement('div');
		this.divContainer.style.background = 'rgba(255, 255, 255, 0.2)';
		this.divContainer.style.paddingTop = '10px';
		// this.divContainer.style.pointerEvents = 'none';
		this.solution.threeCore.host.appendChild(this.divContainer);

		this.divUIRight = document.createElement('div');
		this.divUIRight.style.width = '300px';
		this.divUIRight.style.height = '100px';
		this.divUIRight.style.position = 'absolute';
		this.divUIRight.style.top = '55px';
		this.divUIRight.style.right = '5px';
		this.solution.threeCore.host.appendChild(this.divUIRight);

		const divUI = document.createElement('div');
		this.divUI = divUI;
		divUI.style.width = this._width;
		// divUI.style.height = '100px';
		divUI.style.padding = '5px';
		divUI.style.position = 'absolute';
		divUI.style.zIndex = '10';
		this.divContainer.appendChild(divUI);
		this.solution.threeCore.renderer.domElement.style.position = 'absolute';

		const divBt = document.createElement('button');
		this.divUI.appendChild(divBt);
		divBt.style.width = this._width;
		divBt.textContent = 'Toggle scene';
		divBt.style.fontSize = '11px';
		// divBt.style.background = '#555';
		divBt.style.marginTop = '0px';
		divBt.onclick = () => {
			this.solution.appCore.common.toggleScene();
		};

		const divTitleMeta = document.createElement('div');
		this.metadataPosition = divTitleMeta;
		divTitleMeta.textContent = 'Latitude: 30.23, Day: 286, Hour: 14';
		divTitleMeta.style.fontSize = '20px';
		divTitleMeta.style.width = '100%';
		divTitleMeta.style.height = '100px';
		divTitleMeta.style.paddingTop = '45px';
		divTitleMeta.style.position = 'absolute';
		divTitleMeta.style.textAlign = 'center';
		divTitleMeta.style.zIndex = '10';
		divTitleMeta.style.pointerEvents = 'none';
		this.solution.threeCore.host.appendChild(divTitleMeta);

		const divUITitle = document.createElement('div');
		this.divUI.appendChild(divUITitle);
		divUITitle.style.width = this._width;
		divUITitle.textContent = 'Controllers';
		divUITitle.style.paddingLeft = '10px';
		divUITitle.style.fontSize = '30px';
		divUITitle.style.color = '#222';
		divUITitle.onclick = () => {
			this.toggleController();
		};

		const divUILeft = document.createElement('div');
		this.divUILeft = divUILeft;
		divUILeft.style.width = this._width;
		divUILeft.style.display = 'none';
		divUILeft.style.padding = '5px';
		// div.style.background = '#fefefe';
		// divUILeft.style.position = 'absolute';
		divUILeft.style.zIndex = '10';
		this.divUI.appendChild(divUILeft);

		this.appendLoading();
	}
	public toggleController() {
		this._showUI = !this._showUI;
		if (this._showUI) {
			this.divUILeft.style.display = 'block';
		} else {
			this.divUILeft.style.display = 'none';
		}
	}
	public appendLoading() {
		const loadingDiv = document.createElement('div');
		loadingDiv.id = 'loading';
		loadingDiv.style.position = 'absolute';
		loadingDiv.style.top = '50%';
		loadingDiv.style.left = '50%';
		loadingDiv.style.transform = 'translate(-50%, -50%)';
		loadingDiv.style.zIndex = '9999';
		loadingDiv.style.backgroundColor = 'rgba(255, 255, 255, 0.5)';
		loadingDiv.style.padding = '10px';
		loadingDiv.style.borderRadius = '8px';

		// const path = process.env.PUBLIC_URL + '/static/data/model/map/loading.gif';
		const path = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/loading.gif';
		const loadingImg = document.createElement('img');
		loadingImg.src = path;
		loadingImg.style.backgroundColor = 'transparent';
		loadingImg.alt = 'Loading...';
		loadingImg.width = 120;

		loadingDiv.appendChild(loadingImg);
		this.solution.threeCore.host.appendChild(loadingDiv);
	}
	public initPostUI() {
		const divBtForward = document.createElement('button');
		this.divUILeft.appendChild(divBtForward);
		divBtForward.style.width = this._width;
		divBtForward.textContent = 'changing views forward';
		divBtForward.style.fontSize = '11px';
		divBtForward.onclick = () => {
			this.solution.appCore.common.viewChangingForward();
		};

		const divBtBackward = document.createElement('button');
		this.divUILeft.appendChild(divBtBackward);
		divBtBackward.style.width = this._width;
		divBtBackward.textContent = 'changing views backward';
		divBtBackward.style.fontSize = '11px';
		divBtBackward.onclick = () => {
			this.solution.appCore.common.viewChangingBackward();
		};

		const divBt2 = document.createElement('button');
		this.divUILeft.appendChild(divBt2);
		divBt2.style.width = this._width;
		divBt2.textContent = 'toggle studio env';
		divBt2.style.fontSize = this._fontSize;
		divBt2.onclick = () => {
			this.solution.appCore.common.showEnv = !this.solution.appCore.common.showEnv;
		};

		const divBt3 = document.createElement('button');
		this.divUILeft.appendChild(divBt3);
		divBt3.style.width = this._width;
		divBt3.textContent = 'Shifting HDRI';
		divBt3.style.fontSize = this._fontSize;
		divBt3.onclick = () => {
			this.solution.appCore.common.hdriChanging();
		};

		let checkSubstation = getCheckBox('Substation');
		this.divUILeft.append(checkSubstation.div);
		checkSubstation.checkBox.defaultChecked = this.solution.appCore.common.getSubstationVisibility();
		checkSubstation.checkBox.onchange = () => {
			// if (checkSubstation.checkBox.checked === true){
			//     this.isActive_treated_st = true;
			// } else {
			//     this.isActive_treated_st = false;
			// }
			this.solution.appCore.common.toggleSubstation(checkSubstation.checkBox.checked);
		};

		let checkSubstationDiorama = getCheckBox('Substation Diorama Style');
		this.divUILeft.append(checkSubstationDiorama.div);
		checkSubstationDiorama.div.style.fontSize = '10px';
		checkSubstationDiorama.checkBox.defaultChecked = false;
		checkSubstationDiorama.checkBox.onchange = () => {
			// if (checkSubstationDiorama.checkBox.checked === true){
			//     this.isActive_treated_st = true;
			// } else {
			//     this.isActive_treated_st = false;
			// }
			this.solution.appCore.common.toggleSubstationDiorama(checkSubstationDiorama.checkBox.checked);
		};

		const latSlider = getSlider('lat', -90, 90);
		this.divUILeft.appendChild(latSlider.div);
		latSlider.slider.oninput = () => {
			const value = parseInt(latSlider.slider.value);
			this.solution.appCore.common.solar.latitude = value;
			this.solution.appCore.common.getSunVec(this.solution.appCore.common.solar.latitude, this.solution.appCore.common.solar.day, this.solution.appCore.common.solar.hour);
			// console.log(value);
		};

		const daySlider = getSlider('Day', 1, 365);
		this.divUILeft.appendChild(daySlider.div);
		daySlider.slider.oninput = () => {
			const value = parseInt(daySlider.slider.value);
			this.solution.appCore.common.solar.day = value;
			this.solution.appCore.common.getSunVec(this.solution.appCore.common.solar.latitude, this.solution.appCore.common.solar.day, this.solution.appCore.common.solar.hour);
			// console.log(value);
		};

		const hourSlider = getSlider('Hour', 10, 20);
		this.divUILeft.appendChild(hourSlider.div);
		hourSlider.slider.oninput = () => {
			const value = parseInt(hourSlider.slider.value);
			this.solution.appCore.common.solar.hour = value;
			this.solution.appCore.common.getSunVec(this.solution.appCore.common.solar.latitude, this.solution.appCore.common.solar.day, this.solution.appCore.common.solar.hour);
			// console.log(value);
		};

		const divDrone = document.createElement('button');
		this.divUILeft.appendChild(divDrone);
		divDrone.style.width = this._width;
		divDrone.style.marginTop = '10px';
		divDrone.textContent = 'Running Drone Device...';
		divDrone.style.fontSize = this._fontSize;
		divDrone.onclick = () => {
			this.solution.appCore.common.runningDroneDevices = !this.solution.appCore.common.runningDroneDevices;
		};

		const angleSolarPanel = getSlider('Degree', 0, 20);
		angleSolarPanel.slider.defaultValue = '0';
		this.divUILeft.appendChild(angleSolarPanel.div);
		angleSolarPanel.slider.oninput = () => {
			const value = parseInt(angleSolarPanel.slider.value);
			this.solution.appCore.common.angleSolarPanel(value);
		};

		const divDecompose = document.createElement('button');
		this.divUILeft.appendChild(divDecompose);
		divDecompose.style.width = this._width;
		divDecompose.style.marginTop = '5px';
		divDecompose.textContent = 'Decompose';
		divDecompose.style.fontSize = this._fontSize;
		divDecompose.onclick = () => {
			this.solution.appCore.common.decompose();
		};

		const postProcessing = document.createElement('button');
		this.divUILeft.appendChild(postProcessing);
		postProcessing.style.width = this._width;
		postProcessing.textContent = 'Post processing';
		postProcessing.style.fontSize = this._fontSize;
		postProcessing.onclick = () => {
			this.solution.appCore.common.toggleEffect();
		};

		const divAnimationRotatingA = document.createElement('button');
		this.divUILeft.appendChild(divAnimationRotatingA);
		divAnimationRotatingA.style.width = this._width;
		divAnimationRotatingA.style.marginTop = '10px';
		divAnimationRotatingA.textContent = 'Animation A';
		divAnimationRotatingA.style.fontSize = this._fontSize;
		divAnimationRotatingA.onclick = () => {
			this.solution.appCore.common.toggleAnimationRotatingA();
		};

		const divAnimationRotatingB = document.createElement('button');
		this.divUILeft.appendChild(divAnimationRotatingB);
		divAnimationRotatingB.style.width = this._width;
		divAnimationRotatingB.style.marginTop = '10px';
		divAnimationRotatingB.textContent = 'Animation B';
		divAnimationRotatingB.style.fontSize = this._fontSize;
		divAnimationRotatingB.onclick = () => {
			this.solution.appCore.common.toggleAnimationRotatingB();
		};

		const sliderFOV = getSlider('FOV', 20, 50);
		this.divUILeft.appendChild(sliderFOV.div);
		sliderFOV.slider.oninput = () => {
			const value = parseInt(sliderFOV.slider.value);
			this.solution.appCore.common.changeFOV(value);

			sliderFOV.text.textContent = `FOV: ${value}`;
		};
		this.appendDebugger();
	}
	public appendDebugger() {
		const divTitleDebugger = document.createElement('div');
		divTitleDebugger.textContent = 'Debuggers';
		divTitleDebugger.style.fontSize = '14px';
		divTitleDebugger.style.color = this._color;
		divTitleDebugger.style.paddingTop = '14px';
		this.divUILeft.appendChild(divTitleDebugger);

		const divDecompose = document.createElement('button');
		this.divUILeft.appendChild(divDecompose);
		divDecompose.style.width = this._width;
		divDecompose.textContent = 'Print camera positions';
		divDecompose.style.fontSize = this._fontSize;
		divDecompose.onclick = () => {
			this.solution.appCore.common.printCameraInfo();
		};

		const min = -100000;
		const max = 100000;
		const scale = 0.1;
		const debuggerX = getSlider('X', min, max);
		debuggerX.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerX.div);
		debuggerX.slider.oninput = () => {
			const value = parseFloat(debuggerX.slider.value) * scale;
			this.solution.appCore.common.debuggerX(value);
		};
		const debuggerY = getSlider('Y', min, max);
		debuggerY.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerY.div);
		debuggerY.slider.oninput = () => {
			const value = parseFloat(debuggerY.slider.value) * scale;
			this.solution.appCore.common.debuggerY(value);
		};
		const debuggerZ = getSlider('Z', min, max);
		debuggerZ.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerZ.div);
		debuggerZ.slider.oninput = () => {
			const value = parseFloat(debuggerZ.slider.value) * scale;
			this.solution.appCore.common.debuggerZ(value);
		};

		const minParam = 0;
		const maxParam = 100;
		const scaleParam = 0.01;
		const debuggerA = getSlider('roughness', minParam, maxParam);
		debuggerA.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerA.div);
		debuggerA.slider.oninput = () => {
			const value = parseFloat(debuggerA.slider.value) * scaleParam;
			this.solution.appCore.common.roughness(value);
		};
		const debuggerB = getSlider('metalness', minParam, maxParam);
		debuggerB.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerB.div);
		debuggerB.slider.oninput = () => {
			const value = parseFloat(debuggerB.slider.value) * scaleParam;
			this.solution.appCore.common.metalness(value);
		};
		const debuggerC = getSlider('A', minParam, maxParam);
		debuggerC.slider.defaultValue = '0.0';
		this.divUILeft.appendChild(debuggerC.div);
		debuggerC.slider.oninput = () => {
			const value = parseFloat(debuggerC.slider.value) * scaleParam;
			this.solution.appCore.common.debuggerC(value);
		};
	}
	public showCamera() {
		showCamera(this.divUIRight);
	}

	public showGraph() {
		showGraph(this.divUIRight);
	}

	public showGraphDrone() {
		showGraphDrone(this.divUIRight);
	}

	public destroy() {}
}
