export class Globe {
	public appCore: AppCore;

	envirGeometry: any;
	envirMat: THREE.MeshPhongMaterial;
	envirMesh: THREE.Mesh;

	geometry: THREE.SphereGeometry | any;
	mesh: THREE.Mesh;
	meshCloud: THREE.Mesh;

	pixelMapGlobe: PixelMapGlobe;

	vec: NVector3;
	radius: number = 30;
	xSeg: number = 360;
	ySeg: number = 180;

	t: number = 0.0;

	material: THREE.MeshPhongMaterial | any;
	isDone: boolean = false;

	meshSpot: THREE.Mesh[] = [];

	mapNight: HTMLImageElement;
	mapDay: HTMLImageElement;
	numBaseMapShfit: number = 0;
	bg: boolean;

	lightPivot: THREE.Object3D;

	constructor(appCore: AppCore) {
		this.appCore = appCore;
		this.init();
	}
	public init() {
		this.InitGlobe();

		const lightPivot = new THREE.Object3D();
		this.appCore.scene.add(lightPivot);

		// 조명 자체
		const light = new THREE.DirectionalLight(0xffffff, 1);
		light.position.set(10, 5, 0); // 중심에서 살짝 떨어진 초기 위치
		lightPivot.add(light);

		// 참고용으로 빛 위치에 작은 점 표시
		const lightHelper = new THREE.Mesh(new THREE.SphereGeometry(0.1), new THREE.MeshBasicMaterial({ color: 0xffff00 }));
		light.add(lightHelper);

		// 조명 궤도 기울이기 (예: 23도)
		lightPivot.rotation.z = THREE.MathUtils.degToRad(23);
		this.lightPivot = lightPivot;
	}

	async InitGlobe() {
		this.geometry = new THREE.SphereGeometry(this.radius, this.xSeg, this.ySeg);

		// this.geometry.rotateY(MathUtility.Radians(-180));

		let path = process.env.PUBLIC_URL + '/static/data/map/night-dark-level2.jpg';
		this.mapDay = new Image();
		this.mapDay.src = path; //`njslabSandboxStatic/img/2_no_clouds_4k.jpg`; // earthNoclouds4k;

		this.mapNight = new Image();
		this.mapNight.src = path; //`njslabSandboxStatic/img/night-dark-level2.jpg`; // nightDarkLevel2;

		// this.mapNight.onload = () => {
		this.mapNight.crossOrigin = 'anonymous';
		// let map = THREE.ImageUtils.loadTexture(
		//     `njslabSandboxStatic/img/night-dark-level2.jpg`
		//     // this.mapNight.src
		// );

		let textureLoader = new THREE.TextureLoader();
		// let map = textureLoader.load('njslabSandboxStatic/img/night-dark-level2.jpg');
		let map = textureLoader.load(path);

		this.material = new THREE.MeshPhysicalMaterial({
			color: 0xffffff,
			// specular: 0x050505,
			// shininess: 50,
			map: map,
		});
		this.material.bumpMap = map;
		this.material.bumpScale = 0.01;

		this.mesh = new THREE.Mesh(this.geometry, this.material);

		// }
		this.material.needsUpdate = true;
		this.geometry.uvsNeedUpdate = true;
		// this.geometry.nee = true;
		this.mesh.receiveShadow = true;
		this.mesh.castShadow = true;
		// this.mesh.rotation.x = Math.PI * 0.5;
		// this.mesh.rotation.x = THREE.MathUtils.degToRad(-23.5);

		this.appCore.scene.add(this.mesh);
		// GeometryCommon.listMesh.push(this.mesh);

		usStateLatLong.forEach(({ state, lat, lon }) => {
			this.addLatLongLine(lat, lon, 0.5 + Math.random() * 15.5); // 각 주에 짧은 라인 추가
		});

		// this.addLatLongLine(0, 0, 20);
		// };

		this.connectNearbyStates(usStateLatLong, 3); // 주마다 3개 이웃과 연결
		// this.connectStatesRandomly(usStateLatLong, 31);
	}
	public update() {
		if (this.mesh.visible) {
			// this.mesh.rotation.y += 0.001;

			this.lightPivot.rotation.y += 0.001; // 공전 (조명 도는 속도)
		}
	}
	public show(value: boolean) {
		// console.log(value);
		this.appCore.threeCore.lightWrapper.toggleHDRIBackground(!value);
		this.mesh.visible = value;
		this.appCore.threeCore.scene.background = new THREE.Color(0x000000);

		// this.meshCloud.visible = value;
	}
	public connectNearbyStates(states: typeof usStateLatLong, nearestCount = 3) {
		states.forEach((fromState) => {
			// 다른 모든 주와 거리 계산
			const neighbors = states
				.filter((s) => s !== fromState)
				.map((toState) => ({
					...toState,
					distance: haversineDistance(fromState.lat, fromState.lon, toState.lat, toState.lon),
				}))
				.sort((a, b) => a.distance - b.distance) // 가까운 순 정렬
				.slice(0, nearestCount); // 가까운 N개

			// 가까운 이웃들과 연결
			neighbors.forEach((toState) => {
				this.drawSphericalArc(fromState.lat, fromState.lon, toState.lat, toState.lon, 0x000000);
			});
		});
	}
	public addLatLongLine(lat: number, lon: number, lineLength: number = 1, color = 0xff0000) {
		const pos = latLonToVector3(lat, lon, this.radius);
		const outward = pos
			.clone()
			.normalize()
			.multiplyScalar(this.radius + lineLength);

		const geometry = new THREE.BufferGeometry().setFromPoints([pos, outward]);
		const material = new THREE.LineBasicMaterial({ color });
		const line = new THREE.Line(geometry, material);
		this.appCore.scene.add(line);

		// 구 회전에 따라 line 도 같이 움직이게 하려면 globe에 attach
		this.mesh.add(line);
	}

	public connectStatesRandomly(states: typeof usStateLatLong, radius = 30.01, count: number = 30) {
		const shuffled = [...states].sort(() => Math.random() - 0.5);

		for (let i = 0; i < Math.min(count, shuffled.length - 1); i++) {
			const from = shuffled[i];
			const to = shuffled[i + 1];

			this.drawSphericalArc(from.lat, from.lon, to.lat, to.lon);
		}
	}
	drawSphericalArc(fromLat: number, fromLon: number, toLat: number, toLon: number, color = 0x000000) {
		const from = latLonToVector3(fromLat, fromLon, this.radius);
		const to = latLonToVector3(toLat, toLon, this.radius);
		const arcPoints = createSphericalArc(from, to);

		const geometry = new THREE.BufferGeometry().setFromPoints(arcPoints);
		const material = new THREE.LineBasicMaterial({ color });
		const arcLine = new THREE.Line(geometry, material);

		this.appCore.scene.add(arcLine);
		this.mesh.add(arcLine);
	}
}

function haversineDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
	const R = 6371; // Earth radius (km)
	const toRad = (deg: number) => (deg * Math.PI) / 180;

	const dLat = toRad(lat2 - lat1);
	const dLon = toRad(lon2 - lon1);

	const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;

	const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
	return R * c;
}

function createSphericalArc(from: THREE.Vector3, to: THREE.Vector3, radius = 30, segments = 100): THREE.Vector3[] {
	const arcPoints: THREE.Vector3[] = [];

	const angle = from.angleTo(to); // 중심각 (radian)

	for (let i = 0; i <= segments; i++) {
		const t = i / segments;
		// Slerp: spherical linear interpolation
		const sinTotal = Math.sin(angle);
		const sinFrom = Math.sin((1 - t) * angle);
		const sinTo = Math.sin(t * angle);

		const intermediate = from
			.clone()
			.multiplyScalar(sinFrom)
			.add(to.clone().multiplyScalar(sinTo))
			.divideScalar(sinTotal)
			.normalize()
			.multiplyScalar(radius + 0.1); // 살짝 띄워서 그리기

		arcPoints.push(intermediate);
	}

	return arcPoints;
}

function createGreatCircleCurve(start: THREE.Vector3, end: THREE.Vector3, radius = 30, segments = 64): THREE.Curve<THREE.Vector3> {
	const mid = start
		.clone()
		.add(end)
		.normalize()
		.multiplyScalar(radius + 1.5); // 중심에서 약간 위로
	return new THREE.QuadraticBezierCurve3(start, mid, end);
}

function latLonToVector3(lat: number, lon: number, radius: number): THREE.Vector3 {
	const phi = (90 - lat) * (Math.PI / 180);
	const theta = (lon + 180) * (Math.PI / 180);

	const x = -radius * Math.sin(phi) * Math.cos(theta);
	const z = radius * Math.sin(phi) * Math.sin(theta);
	const y = radius * Math.cos(phi);

	return new THREE.Vector3(x, y, z);
}

