import * as THREE from 'three';
import { DIRECTION } from '../../../Utils/const';
import { Hypercube } from '..';

export class DoorInner {
	public hypercube: Hypercube;
	public meshGroup: THREE.Group;
	private direction: DIRECTION;
	private open = false;

	private closedX = 0;
	private openX = 0;
	private targetX = 0;
	private speed = 0.02; // 0~1 사이로 설정 (0.1이면 부드럽게 움직임)

	constructor(hypercube: Hypercube, meshGroup: THREE.Group, direction: DIRECTION) {
		this.hypercube = hypercube;
		this.meshGroup = meshGroup;
		this.direction = direction;

		this.closedX = meshGroup.position.x;

		const offset = 5.5;
		this.openX = direction === DIRECTION.Left ? this.closedX - offset : this.closedX + offset;

		this.targetX = this.closedX;

		this.hypercube.core.scene.add(this.meshGroup);
	}

	public update() {
		this.meshGroup.position.x += (this.targetX - this.meshGroup.position.x) * this.speed; //* this.hypercube.core.threeCore.rendererWrapper.deltaTime;
	}
	public set visible(v: boolean) {
		this.meshGroup.children.forEach((mesh) => {
			mesh.visible = v;
		});
	}
	public onClick() {
		this.open = !this.open;
		this.targetX = this.open ? this.openX : this.closedX;
		// console.log(`Door is now ${this.open ? "open" : "closed"}`);
	}
}
