import * as THREE from 'three';

import { Solution } from '../';
import { ThreeCore } from '../ThreeCore';
import { AppCommon } from './AppCommon';
import { ActiveCommand } from './ActiveCommand';

import { Hypercube } from './HyperCube';
import { Substation } from './Substation';

import { CLICK_TYPE } from '../Utils/const';
import { Globe } from './Globe';

export class AppCore {
	public solution: Solution;
	public threeCore: ThreeCore;
	public scene: THREE.Scene;

	public common: AppCommon;
	public activeCommand: ActiveCommand;

	public hyperCube: Hypercube;
	public substation: Substation;
	public globe: Globe;

	public navigationScene = true;
	private _init = false;

	constructor(solution: Solution, navigationScene = false) {
		this.solution = solution;
		this.threeCore = solution.threeCore;
		this.scene = solution.threeCore.scene;

		this.navigationScene = navigationScene;

		this.common = new AppCommon(this);
		this.activeCommand = new ActiveCommand(this);
		this.solution.threeCore.readyBinding = () => {
			return this.ready;
		};

		this.initGlobe();
		this.initHypercube();
	}
	public initPost() {
		if (this.hyperCube) this.hyperCube.show(!this.navigationScene);
		if (this.globe) this.globe.show(this.navigationScene);
	}
	public async initGlobe() {
		this.globe = new Globe(this);
	}
	public async initHypercube() {
		this.hyperCube = new Hypercube(this);
		this.substation = new Substation(this);
	}
	public get ready() {
		if (this.substation && this.hyperCube && this.substation.ready && this.hyperCube.ready) {
			if (!this._init) {
				this.initPost();
				this._init = true;
			}
			return true;
		} else {
			return false;
		}
	}
	public update() {
		let animation = false;
		if (this.hyperCube) {
			if (this.hyperCube.update()) {
				animation = true;
			}
		}
		if (this.globe) this.globe.update();

		return animation;
	}
	public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
		this.activeCommand.onMouseEventListener(e, type);
	}

	public destroy() {}
	public showStudioEnv(v) {
		if (this.hyperCube) this.hyperCube.show(v);
		if (this.globe) this.globe.show(!v);
	}
}
